mapper.sql:
FROM AUCTION a JOIN PRODUCT p ON p.PRD_SN = a.PRD_SN JOIN USERS seller ON seller.USR_SN = p.USR_SN LEFT JOIN CMM_CODE product_status ON product_status.CMM_CD = p.PRD_STATUS_CD LEFT JOIN CMM_CODE auction_status ON auction_status.CMM_CD = a.AUC_STATUS_CD LEFT JOIN ( SELECT AUC_SN, COUNT(*) AS BID_COUNT FROM BID GROUP BY AUC_SN ) bid ON bid.AUC_SN = a.AUC_SN LEFT JOIN TRADE trade ON trade.TRD_SN = ( SELECT t.TRD_SN FROM TRADE t WHERE t.PRD_SN = p.PRD_SN AND t.TRD_TYPE_CD = 'TRDC0001' ORDER BY t.TRD_REG_DT DESC, t.TRD_SN DESC LIMIT 1 ) LEFT JOIN CMM_CODE trade_status ON trade_status.CMM_CD = trade.TRD_STATUS_CD LEFT JOIN AUCTION_CANCEL_REQUEST cancel_request ON cancel_request.AUC_CNL_REQ_SN = ( SELECT r.AUC_CNL_REQ_SN FROM AUCTION_CANCEL_REQUEST r WHERE r.AUC_SN = a.AUC_SN AND r.AUC_CNL_REQ_APRV_YN IS NULL ORDER BY r.AUC_CNL_REQ_REG_DT DESC, r.AUC_CNL_REQ_SN DESC LIMIT 1 ) WHERE p.PRD_USE_YN = 'Y'
AND (p.PRD_NM LIKE CONCAT('%', #{condition.keyword}, '%') OR seller.USR_NM LIKE CONCAT('%', #{condition.keyword}, '%') OR CAST(a.AUC_SN AS CHAR) LIKE CONCAT('%', #{condition.keyword}, '%'))
AND a.AUC_STATUS_CD = #{condition.auctionStatusCode}
AND trade.TRD_STATUS_CD = #{condition.tradeStatusCode}
AND cancel_request.AUC_CNL_REQ_SN IS NOT NULL
AND cancel_request.AUC_CNL_REQ_SN IS NULL
AND a.AUC_REG_DT >= #{condition.registeredFrom}
AND a.AUC_REG_DT < DATE_ADD(#{condition.registeredTo}, INTERVAL 1 DAY)
